package com.bqsqwad.heartbreakhealer.core.ui.components

import android.graphics.BitmapFactory
import android.util.Base64
import androidx.compose.foundation.Image
import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.asImageBitmap
import androidx.compose.ui.layout.ContentScale

/** The supplied official Heartbreak Healer healed-heart logo, embedded as an optimized WebP asset. */
private const val OFFICIAL_LOGO_WEBP = ""

@Composable
fun HeartbreakHealerLogo(modifier: Modifier = Modifier, contentScale: ContentScale = ContentScale.Fit) {
    val bitmap = remember {
        val bytes = Base64.decode(OFFICIAL_LOGO_WEBP, Base64.DEFAULT)
        BitmapFactory.decodeByteArray(bytes, 0, bytes.size)?.asImageBitmap()
    }
    if (bitmap != null) {
        Image(bitmap = bitmap, contentDescription = "Heartbreak Healer official healed-heart logo", modifier = modifier, contentScale = contentScale)
    }
}
